import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { MatAutocompleteModule } from '@angular/material/autocomplete';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { Observable } from 'rxjs';
import { map, startWith } from 'rxjs/operators';

@Component({
  selector: 'app-example',
  standalone: true,
  imports: [MatAutocompleteModule, MatFormFieldModule, MatInputModule, ReactiveFormsModule, CommonModule],
  template: `
    <mat-form-field>
      <mat-label>Fruit</mat-label>
      <input matInput [formControl]="control" [matAutocomplete]="auto" />
    </mat-form-field>
    <mat-autocomplete #auto="matAutocomplete">
      <mat-option *ngFor="let option of filteredOptions$ | async" [value]="option">
        {{ option }}
      </mat-option>
    </mat-autocomplete>
  `,
})
export class ExampleComponent {
  control = new FormControl('');
  options = ['Apple', 'Banana', 'Cherry'];
  filteredOptions$: Observable<string[]> = this.control.valueChanges.pipe(
    startWith(''),
    map((value) => this.options.filter((option) => option.toLowerCase().includes((value ?? '').toLowerCase()))),
  );
}
